/* Observe -> predict -> test: learning is driven by measured gameplay, not scripted wins. */
const CafeBeforeLearning=CampaignCafe;
CampaignCafe=class extends CafeBeforeLearning{
 constructor(...args){super(...args);this.rushAt=this.shift===3?95:130;this.arrivals=this.shift===3?[0,25,50,75,95,115,135,155]:[0,35,70,105,130,155,180,205];this.evidence={slotWait:0,foodWait:0,readyWait:0,orderWait:0,slotCustomers:new Set(),foodCustomers:new Set(),overlap:new Set(),breakdown:{order:0,oven:0,handoff:0,drink:0}};this.tick(.001);}
 addOrder(){const o=super.addOrder();if(o.recipe.coffee&&!o.recipe.bakery&&(o.id<=6||o.id%4!==0)){o.recipe.bakery=MENU.bakery[(o.id-1)%3];o.type='combo';o.price+=o.recipe.bakery==='Breakfast Sandwich'?3.5:o.recipe.bakery==='Croissant'?1.75:1.5;}o.story=['I’m picking up breakfast before class.','My study group is waiting for me.','A treat before my bus arrives.','I stop here before work.','Coffee for a busy school morning.'][((o.id||1)-1)%5];return o;}
 get arrivalRate(){return this.id>=this.arrivals.length?0:this.shift===3?(this.time<95?2:3):(this.time<130?1.7:2.4);}
 loadOven(slot,item,o=this.active){const ok=super.loadOven(slot,item,o);if(ok){const duration=this.upgrades.has('oven')?25:45;this.ovenSlots[slot].duration=duration;this.jobs.find(j=>j.worker==='oven'&&j.slot===slot).duration=duration;}return ok;}
 benchmark(o){return Math.max(super.benchmark(o),o.recipe.bakery?65:0);}
 statusFor(o){if(!o.accepted)return 'Waiting to order';if(this.ready(o))return '✓ Ready for pickup';const slot=this.ovenSlots.find(s=>s?.id===o.id),drinkReady=!o.recipe.coffee||o.lid;if(slot?.ready)return 'Food ready · collect it';if(drinkReady&&o.recipe.bakery&&!o.bakeryResult)return slot?'Drink ready · food baking':this.ovenSlots.every(Boolean)?'Waiting for oven space':'Drink ready · food not started';if(o.recipe.bakery&&!o.bakeryResult&&!slot&&this.ovenSlots.every(Boolean))return 'Waiting for oven space';return slot?'Food baking · drink in progress':'Drink in progress';}
 tick(dt){if(this.evidence&&!this.finished){const d=Math.min(dt,this.duration-this.time);for(const o of this.orders){if(!o.accepted){this.evidence.orderWait+=d;this.evidence.breakdown.order+=d;continue;}if(this.ready(o)){this.evidence.readyWait+=d;this.evidence.breakdown.handoff+=d;continue;}const slot=this.ovenSlots.find(s=>s?.id===o.id);const foodBlocking=o.recipe.bakery&&!o.bakeryResult&&((!o.recipe.coffee||o.lid)||(!slot&&this.ovenSlots.every(Boolean)));this.evidence.breakdown[foodBlocking?'oven':'drink']+=d;if(o.recipe.bakery&&!o.bakeryResult&&!slot&&this.ovenSlots.every(Boolean)){this.evidence.slotWait+=d;this.evidence.slotCustomers.add(o.id);}if(o.recipe.coffee&&o.lid&&o.recipe.bakery&&!o.bakeryResult){this.evidence.foodWait+=d;this.evidence.foodCustomers.add(o.id);}if(this.activity&&['syrup','milk','coffee','topping'].includes(this.activity)&&this.jobs.some(j=>j.worker==='oven'))this.evidence.overlap.add(o.id);}}super.tick(dt);}
 report(){const r=super.report();const e=this.evidence;return {...r,evidence:e?{slotWait:e.slotWait,foodWait:e.foodWait,readyWait:e.readyWait,orderWait:e.orderWait,slotCustomers:e.slotCustomers.size,foodCustomers:e.foodCustomers.size,overlap:e.overlap.size,breakdown:{...e.breakdown}}:null};}
};
POWERUPS.find(u=>u.id==='oven').benefit='Bake each item in 25 seconds instead of 45.';
const learningBegin=beginCampaignShift,learningUpdate=update,learningReport=showReport,learningShop=showShop,learningBaking=openBaking,learningPreview=preview,learningHandoff=handoff;
function storyCard(title,body,actions){paused=true;closeStation();document.querySelector('.modal-backdrop')?.remove();modalKind='story';const e=document.createElement('div');e.className='modal-backdrop';e.innerHTML=`<section class="modal learning-card" role="dialog" aria-modal="true"><small>rISE · THE MORNING RUSH</small><h2>${title}</h2><p>${body}</p><div class="story-actions">${actions.map((a,i)=>`<button class="big-btn ${i?'gold':''}" data-story="${i}">${a.label}</button>`).join('')}</div></section>`;document.body.appendChild(e);e.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{closeModal();actions[+b.dataset.story].run();});e.querySelector('button').focus();}
beginCampaignShift=function(){learningBegin();storyCard(['','Can you save the morning rush?','Test your idea','Can your café handle a bigger rush?'][sim.shift],['','“People love our coffee, but breakfast orders keep backing up. Customers will arrive one at a time. Work this shift and find out where we’re losing time.”<br><br><b>Your mystery:</b> what is keeping customers from getting their orders?','The same customers will arrive with the same orders. Try your improvements and compare the results. A different strategy can matter as much as equipment.','The first customer is here. Each next customer enters separately. Closer arrivals and bakery orders will test the process you improved. Watch for a new bottleneck.'][sim.shift],[{label:sim.shift===1?'Investigate the café →':'Open the café →',run:()=>{}}]);};
update=function(){learningUpdate();if(!sim||sim.tutorial||sim.finished)return;for(const el of document.querySelectorAll('[data-customer]')){const o=sim.orders.find(o=>o.id===+el.dataset.customer);if(o){el.querySelector('.customer-label small').textContent=sim.statusFor(o);el.title=o.story;}}const cloud=document.querySelector('#order-cloud');if(sim.active&&cloud&&!cloud.querySelector('.customer-story'))cloud.insertAdjacentHTML('afterbegin',`<small class="customer-story">${sim.active.story}</small>`);document.querySelector('#instruction').textContent=sim.active&&!sim.active.accepted?'Select a customer to take their order.':sim.active&&sim.ready()?'An order is ready. Hand it over to move the line.':'Watch what each customer is waiting for. Choose your next task.';};
openBaking=function(){learningBaking();if(!sim.tutorial&&stationPanel?.key==='baking')document.querySelector('.baking-dialog header small').textContent=`${sim.ovenSlots.length} slots · ${sim.upgrades.has('oven')?25:45} seconds each`;};
preview=function(u){return learningPreview(u).replace('20s → 12s','45s → 25s').replace('12s <span>','25s <span>');};
function diagnosis(r){return Object.entries(r.evidence.breakdown).sort((a,b)=>b[1]-a[1])[0];}
const diagnosisLabels={order:'Taking orders',oven:'Bakery and oven delays',handoff:'Handing over ready orders',drink:'Drink preparation'};
function mysteryPrompt(r){const area=document.createElement('section');area.className='mystery-review';area.innerHTML=`<small>CAFÉ MYSTERY</small><h2>Where did the most work pile up?</h2><p>Choose what you noticed most.</p><div class="diagnosis-choices">${Object.entries(diagnosisLabels).map(([k,v])=>`<button class="small-btn" data-diagnose="${k}">${v}</button>`).join('')}</div>`;document.querySelector('.report-actions').before(area);document.querySelector('#go-shop')?.setAttribute('disabled','');area.querySelectorAll('button').forEach(b=>b.onclick=()=>{r.guess=b.dataset.diagnose;showReport();});}
function achievementList(r){const first=journey.reports[0],badges=[];if(r.evidence.overlap>0)badges.push(['Multitasking Master','You worked on a drink while the oven was running.']);const d=diagnosis(r);if(r.guess===d[0]&&d[1]>0)badges.push(['Bottleneck Detective','Your diagnosis matched the largest measured delay category.']);if(r.shift>1&&r.served>=first.served&&r.served>0&&first.served>0&&r.wait<first.wait&&r.quality>=first.quality)badges.push(['Quality Keeper','You reduced completed-customer time without lowering quality or serving fewer customers.']);if(r.shift>1&&r.served>=first.served&&r.served>0&&first.served>0&&r.wait<first.wait&&journey.cash>=0)badges.push(['Smart Spender','You improved waiting time, maintained throughput, and stayed within budget.']);return badges;}
function nextShiftSuggestion(r,cause){
 const prefix=r.shift===3?'Next journey':'Next shift';
 if(!r.evidence.overlap)return `${prefix}, try overlapping baking and drink preparation, then compare your results.`;
 if(r.returns>0)return `${prefix}, check the ticket and collect baked items promptly to reduce remakes.`;
 if(cause==='handoff')return `${prefix}, hand over ready orders before starting another drink.`;
 if(cause==='order')return `${prefix}, take the next order while food is baking.`;
 if(cause==='oven')return `${prefix}, start baking earlier and prepare drinks while the oven runs.`;
 return `${prefix}, follow the ticket from syrup to milk to coffee to keep preparation moving.`;
}
showReport=function(){learningReport();const r=journey.reports.at(-1);if(!r?.evidence)return;const report=document.querySelector('.shift-report');if(!r.guess){mysteryPrompt(r);return;}const [cause,seconds]=diagnosis(r),e=r.evidence;const panel=document.createElement('section');panel.className='mystery-review';panel.innerHTML=`<small>YOUR INVESTIGATION</small><h2>${r.guess===cause?'Your observation matched the evidence!':'Here’s what the records showed'}</h2><p>Your choice: <b>${diagnosisLabels[r.guess]}</b><br>Largest measured delay: <b>${diagnosisLabels[cause]}</b></p></section>`;report.querySelector('.report-actions').before(panel);const badges=achievementList(r);const badge=document.createElement('section');badge.className='learning-badges';badge.innerHTML=`<h2>Decisions worth celebrating</h2>${badges.length?badges.map(([n,t])=>`<article><b>★ ${n}</b><p>${t}</p></article>`).join(''):''}`;report.querySelector('.mystery-review').before(badge);const tip=nextShiftSuggestion(r,cause);badge.insertAdjacentHTML('beforeend',`<div class="next-shift-tip"><small>${r.shift===3?'TRY NEXT JOURNEY':'TRY NEXT SHIFT'}</small><p>${tip}</p></div>`);if(r.shift>1&&journey.predictions?.[r.shift]){const p=journey.predictions[r.shift],before=journey.reports.find(x=>x.shift===r.shift-1),metric={wait:'Average time in café',quality:'Order quality',profit:'Shift profit'}[p],delta=r[p]-before[p],enough=p==='profit'||(r.served>0&&before.served>0),improved=p==='wait'?delta<0:delta>0;badge.insertAdjacentHTML('beforebegin',`<section class="prediction-review"><h2>Did your prediction hold up?</h2><p>You predicted an improvement in <b>${metric}</b>.</p><p>${before[p].toFixed(1)} → ${r[p].toFixed(1)}${p==='wait'?' seconds':p==='quality'?'%':' dollars'} · <b>${!enough?'Not enough completed orders to compare':Math.abs(delta)<.05?'Unchanged':improved?'Improved':'Did not improve'}</b></p></section>`);}if(r.shift===3){const total=journey.reports.reduce((n,x)=>n+x.served,0);badge.insertAdjacentHTML('beforeend',`<p class="owner-feedback">${total} customers served across your three-shift journey.</p>`);}};
showShop=function(){learningShop();const next=document.querySelector('#begin-next');const run=next.onclick;next.onclick=()=>{storyCard('Make your prediction','What do you expect your choices to improve most? We’ll compare this with your results after the shift.',[{label:'Shorter customer waits',run:()=>predict('wait')},{label:'Better order quality',run:()=>predict('quality')},{label:'Higher profit',run:()=>predict('profit')}]);function predict(k){journey.predictions??={};journey.predictions[journey.shift+1]=k;run();}};};
// Wrong orders create a real speed/quality choice rather than a hidden score penalty.
handoff=function(){if(sim?.tutorial||!sim?.ready()){learningHandoff();return;}const o=sim.active,s=sim.scores(o);if(s.accuracy>=90){learningHandoff();return;}storyCard('Quality check: serve or remake?',`This order’s accuracy is <b>${s.accuracy}%</b>. Serving keeps the line moving, but lowers satisfaction and possible tips. Remaking uses ingredients and more time.`,[{label:'Remake · $0.60',run:()=>{if(o.recipe.coffee)sim.retry('syrup',o);if(o.recipe.bakery&&s.bakeryAccuracy<90){o.bakeryResult=null;o.progress.baking=0;}sim.costs+=.6;update();}},{label:'Serve as made',run:()=>learningHandoff()}]);};
